WHERE slug IN ('what-keeps-a-student-learning', 'health-starts-close-to-home', 'why-local-mentors-matter', 'what-community-led-means', 'small-barriers-big-difference', 'measuring-progress-with-dignity');

UPDATE blog_posts SET featured = FALSE, updated_at = NOW() WHERE featured = TRUE;

INSERT INTO blog_posts (
    id, slug, category, format, status, featured, display_order,
    cover_image_url, published_at, translations, created_at, updated_at
) VALUES
(gen_random_uuid(), 'a-school-bag-a-place-at-school', 'Education', 'ARTICLE', 'PUBLISHED', true, 1, '/images/sharehope-cover.png', TIMESTAMP WITH TIME ZONE '2026-11-07 12:00:00+00', $blog$ {"en":{"title":"A school bag, a place at school","excerpt":"This week, ShareHope handed out new school bags to children in need. A short story from the field about why school supplies matter.","body":"For a child, a school bag is more than something to carry books in. It means: I belong at school, like everyone else.\n\nThis week, we handed out new school bags to children in need: a little boy in a white shirt, a girl in a yellow dress, and a young orphan boy dressed in khaki.\n\nOur founder knows that feeling well. As a child, she spent three years out of school because her family could not afford it. \"I know how terrible that feeling is,\" she says. That is why school kits were the very first thing we ever did.\n\nThe same week, a widow was moved to tears when she learned that ShareHope would cover her children's school supplies. Raising her children alone, she had not expected anyone to think of her family. Her surprise was immense.\n\nA pen, a notebook, or a bag can seem small. For a child who almost didn't go to school, it can change everything.","imageAlt":"A smiling girl holding her new school backpack","buttonText":"Read more","authorName":"ShareHope Team","seoTitle":"A school bag, a place at school | ShareHope","seoDescription":"This week, ShareHope handed out new school bags to children in need. A short story from the field about why school supplies matter.","tags":["Education","School Supplies"]},"fr":{"title":"Un sac d'école, une place à l'école","excerpt":"Cette semaine, ShareHope a remis de nouveaux sacs d'école à des enfants démunis. Une histoire du terrain sur l'importance des fournitures scolaires.","body":"Pour un enfant, un sac d'école est bien plus qu'un objet pour porter ses cahiers. Il veut dire : j'ai ma place à l'école, comme les autres.\n\nCette semaine, nous avons remis de nouveaux sacs d'école à des enfants démunis : un petit garçon en chemise blanche, une fillette en robe jaune et un jeune garçon orphelin vêtu de kaki.\n\nNotre fondatrice connaît bien ce sentiment. Enfant, elle est restée trois ans sans aller à l'école, faute de moyens. « Je sais combien ce sentiment est effroyable », dit-elle. C'est pour cela que les kits scolaires ont été la toute première chose que nous avons faite.\n\nLa même semaine, une veuve a été émue aux larmes en apprenant que ShareHope prendrait en charge les fournitures scolaires de ses enfants. Élevant seule ses enfants, elle ne s'attendait pas à ce que quelqu'un pense à sa famille. Sa surprise a été immense.\n\nUn stylo, un cahier ou un sac peuvent sembler peu de chose. Pour un enfant qui a failli ne pas aller à l'école, ils peuvent tout changer.","imageAlt":"Une fillette souriante tenant son nouveau sac d'école","buttonText":"Lire la suite","authorName":"L'équipe ShareHope","seoTitle":"Un sac d'école, une place à l'école | ShareHope","seoDescription":"Cette semaine, ShareHope a remis de nouveaux sacs d'école à des enfants démunis. Une histoire du terrain sur l'importance des fournitures scolaires.","tags":["Éducation","Fournitures scolaires"]}}$blog$::jsonb, NOW(), NOW()),
(gen_random_uuid(), 'standing-with-widows', 'Community', 'ARTICLE', 'PUBLISHED', false, 2, 'https://images.unsplash.com/photo-1532629345422-7515f3d16bb6?auto=format&fit=crop&w=1200&q=80', TIMESTAMP WITH TIME ZONE '2026-11-05 12:00:00+00', $blog$ {"en":{"title":"Standing with widows","excerpt":"Behind every gift is a story. This month, ShareHope gave financial support to four widows raising their children alone.","body":"Scripture asks us to look after widows in their distress. At ShareHope, that is not an idea. It is women we know, and families we walk beside.\n\nThis month, we gave financial support to four widows: three gifts of 20,000 F CFA and one of 10,000 F CFA. For families with almost nothing, it means food on the table, help with school costs, or the start of a small trade.\n\nOne of them is a young widow nursing her baby, who has had nowhere to sleep but the church. Another is raising four children on her own; feeding, clothing, and schooling them alone is a daily struggle, and every bit of support lightens the load.\n\nA third widow cried when she learned that ShareHope would cover her children's school supplies. She had not expected anyone to think of her.\n\nWhen we hear what the families we help say about ShareHope, we are often moved to tears too. They tell us they found hope again because someone cares. That is why we keep going, and why we cannot do it alone.","imageAlt":"A widow receiving a visit at home","buttonText":"Read more","authorName":"ShareHope Team","seoTitle":"Standing with widows | ShareHope","seoDescription":"Behind every gift is a story. This month, ShareHope gave financial support to four widows raising their children alone.","tags":["Community","Widows"]},"fr":{"title":"Aux côtés des veuves","excerpt":"Derrière chaque don, il y a une histoire. Ce mois-ci, ShareHope a apporté un soutien financier à quatre veuves qui élèvent seules leurs enfants.","body":"L'Écriture nous demande de visiter les veuves dans leurs afflictions. Chez ShareHope, ce n'est pas une idée : ce sont des femmes que nous connaissons, et des familles que nous accompagnons.\n\nCe mois-ci, nous avons apporté un soutien financier à quatre veuves : trois dons de 20 000 F CFA et un de 10 000 F CFA. Pour des familles qui n'ont presque rien, cela veut dire de la nourriture sur la table, une aide pour les frais scolaires ou le début d'un petit commerce.\n\nL'une d'elles est une jeune veuve qui allaite son bébé et qui n'a eu d'autre endroit où dormir que l'église. Une autre élève seule ses quatre enfants : les nourrir, les vêtir et les scolariser est un combat quotidien, et chaque soutien allège un peu le fardeau.\n\nUne troisième veuve a pleuré en apprenant que ShareHope prendrait en charge les fournitures scolaires de ses enfants. Elle ne s'attendait pas à ce que quelqu'un pense à elle.\n\nQuand nous entendons ce que les familles disent de ShareHope, nous sommes souvent émus aux larmes nous aussi. Elles nous disent avoir retrouvé l'espoir parce que quelqu'un se soucie d'elles. C'est pour cela que nous continuons, et que nous ne pouvons pas le faire seuls.","imageAlt":"Une veuve reçoit une visite chez elle","buttonText":"Lire la suite","authorName":"L'équipe ShareHope","seoTitle":"Aux côtés des veuves | ShareHope","seoDescription":"Derrière chaque don, il y a une histoire. Ce mois-ci, ShareHope a apporté un soutien financier à quatre veuves qui élèvent seules leurs enfants.","tags":["Communauté","Veuves"]}}$blog$::jsonb, NOW(), NOW()),
(gen_random_uuid(), 'a-glass-of-water', 'Field Notes', 'ARTICLE', 'PUBLISHED', false, 3, '/images/sharehope-hero-collage.png', TIMESTAMP WITH TIME ZONE '2026-11-03 12:00:00+00', $blog$ {"en":{"title":"A glass of water: why ShareHope exists","excerpt":"Our founder grew up knowing hunger, hardship, and years without school. Out of that childhood came a promise, and that promise became ShareHope.","body":"Some days, there was nothing to eat. Our founder was raised by her paternal grandmother, who pawned her wraps and jewelry to put food on the table, and sometimes could not find the money to get them back. When everything had been pawned, they went days without eating.\n\nOn those days, when the little girl said she was hungry, her grandmother would answer gently: \"Go drink a glass of water, and bring me one too.\" Some days, they drank porridge without sugar.\n\nLater, her father took her in, and life became easier until he passed away while she was still in school. With no money and no support, she stayed home for three years, until an uncle she still admires sent her back to school.\n\nHer mother had suffered too. During her pregnancy, she struggled to find food and had to borrow clothes from her sisters. After the birth, she could barely feed her child or pay medical bills, while the father was away in another country.\n\nIn those difficult years, she made herself a promise: she would do everything she could so that no child, no pregnant woman, no human being would go through what she went through. That promise is ShareHope.\n\nToday, when we hand a school bag to a child or sit beside a sick child in hospital, we are keeping that promise. And we know from experience that the little we have can do far more than we think.","imageAlt":"Children and families supported by ShareHope","buttonText":"Read more","authorName":"ShareHope Team","seoTitle":"A glass of water: why ShareHope exists | ShareHope","seoDescription":"Our founder grew up knowing hunger, hardship, and years without school. Out of that childhood came a promise, and that promise became ShareHope.","tags":["Our Story","Founder"]},"fr":{"title":"Un verre d'eau : pourquoi ShareHope existe","excerpt":"Notre fondatrice a connu la faim, les difficultés et des années sans école. De cette enfance est née une promesse, et cette promesse est devenue ShareHope.","body":"Certains jours, il n'y avait rien à manger. Notre fondatrice a été élevée par sa grand-mère paternelle, qui mettait ses pagnes et ses bijoux en gage pour nourrir la famille, et qui parfois ne trouvait pas l'argent pour les récupérer. Quand tout avait été mis en gage, elles restaient des jours sans manger.\n\nCes jours-là, quand la petite fille disait qu'elle avait faim, sa grand-mère lui répondait doucement : « Va boire un verre d'eau, et apporte-m'en un aussi. » Certains jours, elles buvaient la bouillie sans sucre.\n\nPlus tard, son père l'a récupérée, et la vie est devenue plus douce, jusqu'à ce qu'il décède alors qu'elle était encore sur les bancs de l'école. Faute de moyens et de soutien, elle est restée trois ans à la maison, jusqu'à ce qu'un oncle qu'elle admire encore la rescolarise.\n\nSa mère aussi avait souffert. Pendant sa grossesse, elle avait du mal à trouver à manger et devait demander des habits à ses sœurs. Après la naissance, elle pouvait à peine nourrir son enfant ou payer les factures médicales, pendant que le père était parti dans un autre pays.\n\nPendant ces années difficiles, elle s'est fait une promesse : tout faire pour qu'aucun enfant, aucune femme enceinte, aucun être humain ne traverse ce qu'elle a traversé. Cette promesse, c'est ShareHope.\n\nAujourd'hui, quand nous remettons un sac d'école à un enfant ou que nous nous asseyons au chevet d'un enfant malade, nous tenons cette promesse. Et nous savons par expérience que le peu que nous avons peut faire bien plus qu'on ne le croit.","imageAlt":"Des enfants et des familles soutenus par ShareHope","buttonText":"Lire la suite","authorName":"L'équipe ShareHope","seoTitle":"Un verre d'eau : pourquoi ShareHope existe | ShareHope","seoDescription":"Notre fondatrice a connu la faim, les difficultés et des années sans école. De cette enfance est née une promesse, et cette promesse est devenue ShareHope.","tags":["Notre histoire","Fondatrice"]}}$blog$::jsonb, NOW(), NOW()),
(gen_random_uuid(), 'from-peoples-care-center-to-sharehope', 'Community', 'ARTICLE', 'PUBLISHED', false, 4, '/images/education-hero-group.png', TIMESTAMP WITH TIME ZONE '2026-11-01 12:00:00+00', $blog$ {"en":{"title":"From People's Care Center to ShareHope","excerpt":"What began in 2022 as People's Care Center has grown into ShareHope. Here is how we got here, one step at a time.","body":"Every organization has a beginning. Ours was small, close to home, and driven by one simple question: who needs help right now?\n\n2022: Where it began. We started as People's Care Center. Our first focus was children in need, whose parents could not afford school supplies or, sometimes, even daily meals. We shared school supplies and food, and helped some young people into apprenticeships such as sewing, so they could learn a trade and build a future.\n\n2023: Growing. As we got to know the community better, we saw new needs. We began visiting sick children in hospital, praying with them and bringing food. We distributed food at Christmas to families who cannot provide three meals a day, and started helping single mothers launch a small trade to support their children.\n\n2026: A new name, the same promise. People's Care Center became ShareHope. The name changed, but the heart of the work did not: we still share the little we have, wherever the need is greatest.\n\nThree convictions have guided us from the start. If we wait until we have more than enough to give, we will never give. We must look for where the needs are, and be the solution. And the little we have can do much more than we think.","imageAlt":"Children holding the school supplies they received","buttonText":"Read more","authorName":"ShareHope Team","seoTitle":"From People's Care Center to ShareHope | ShareHope","seoDescription":"What began in 2022 as People's Care Center has grown into ShareHope. Here is how we got here, one step at a time.","tags":["Our Story","Community"]},"fr":{"title":"De People's Care Center à ShareHope","excerpt":"Ce qui a commencé en 2022 sous le nom de People's Care Center est devenu ShareHope. Voici notre parcours, une étape à la fois.","body":"Chaque organisation a un commencement. Le nôtre était modeste, tout proche, et guidé par une question simple : qui a besoin d'aide en ce moment ?\n\n2022 : le point de départ. Nous avons commencé sous le nom de People's Care Center. Notre première priorité : les enfants démunis, dont les parents ne pouvaient pas acheter les fournitures scolaires ni, parfois, assurer les repas de chaque jour. Nous avons partagé des fournitures et des vivres, et aidé certains jeunes à entrer en apprentissage, comme la couture, pour apprendre un métier et bâtir leur avenir.\n\n2023 : la croissance. En apprenant à mieux connaître la communauté, nous avons vu de nouveaux besoins. Nous avons commencé à rendre visite aux enfants malades à l'hôpital, à prier avec eux et à apporter des vivres. Nous avons distribué des vivres à Noël aux familles qui ne peuvent pas assurer trois repas par jour, et commencé à aider des mères célibataires à lancer un petit commerce pour subvenir aux besoins de leurs enfants.\n\n2026 : un nouveau nom, la même promesse. People's Care Center est devenu ShareHope. Le nom a changé, mais le cœur du travail est resté le même : nous partageons toujours le peu que nous avons, là où le besoin est le plus grand.\n\nTrois convictions nous guident depuis le début. S'il faut attendre le superflu pour donner, on ne donnera jamais. Il faut chercher où sont les besoins, et en être la solution. Et le peu que nous avons peut faire beaucoup plus qu'on ne le croit.","imageAlt":"Des enfants tenant les fournitures scolaires reçues","buttonText":"Lire la suite","authorName":"L'équipe ShareHope","seoTitle":"De People's Care Center à ShareHope | ShareHope","seoDescription":"Ce qui a commencé en 2022 sous le nom de People's Care Center est devenu ShareHope. Voici notre parcours, une étape à la fois.","tags":["Notre histoire","Communauté"]}}$blog$::jsonb, NOW(), NOW())
